const item = $json;
let origen, nombre, telefono, mensaje, servicio_interes;

// Detecta si viene de WhatsApp (Twilio) o del formulario
if (item.body && item.body.From) {
  origen = 'whatsapp';
  telefono = item.body.WaId;
  mensaje = item.body.Body;
  nombre = item.body.ProfileName || 'Sin nombre (WhatsApp)';
  servicio_interes = 'No especificado';
} else {
  origen = 'formulario_web';
  nombre = item.body.nombre;
  telefono = item.body.telefono;
  mensaje = item.body.mensaje;
  servicio_interes = item.body.servicio_interes || 'No especificado';
}

return {
  origen,
  nombre,
  telefono,
  mensaje,
  servicio_interes,
  fecha_ingreso: new Date().toISOString()
};

