const ayer = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
const items = $input.all().map(i => i.json);

const leads = items.filter(i => i.categoria !== undefined);
const citas = items.filter(i => i.hora !== undefined && i.nombre_cliente !== undefined);
const nutricion = items.filter(i => i.mensaje_nutricion !== undefined);

const leadsAyer = leads.filter(l => l.fecha_ingreso && l.fecha_ingreso.startsWith(ayer));
const citasAyer = citas.filter(c => c.fecha === ayer);
const nutricionAyer = nutricion.filter(n => n.fecha_envio === ayer);

const porCategoria = { caliente: 0, tibio: 0, frio: 0 };
leadsAyer.forEach(l => { if (porCategoria[l.categoria] !== undefined) porCategoria[l.categoria]++; });

return {
  fecha: ayer,
  total_leads_hoy: leadsAyer.length,
  leads_calientes: porCategoria.caliente,
  leads_tibios: porCategoria.tibio,
  leads_frios: porCategoria.frio,
  citas_agendadas_hoy: citasAyer.length,
  leads_en_nutricion_hoy: nutricionAyer.length,
  detalle_leads: leadsAyer
};

