const hoy = $now;
const haceUnaSemana = hoy.minus({ days: 7 });

const citas = $input.all().map(i => i.json).filter(c => c.fecha); // descarta el item vacío de Always Output Data

const citasSemana = citas.filter(c => {
  const fechaCita = new Date(c.fecha);
  return fechaCita >= haceUnaSemana.toJSDate() && fechaCita <= hoy.toJSDate();
});

const ingresoTotal = citasSemana.reduce((sum, c) => sum + (Number(c.monto_facturado) || 0), 0);

// Costo operativo estimado fijo mensual / 4 semanas (mismo criterio de P19)
const costoOperativoSemanal = 800000; // ajustable: arriendo, insumos, nómina prorrateada

const roi = costoOperativoSemanal > 0
  ? (((ingresoTotal - costoOperativoSemanal) / costoOperativoSemanal) * 100).toFixed(1)
  : 0;

return {
  fecha_reporte: hoy.toFormat('yyyy-MM-dd'),
  periodo: `${haceUnaSemana.toFormat('yyyy-MM-dd')} a ${hoy.toFormat('yyyy-MM-dd')}`,
  cantidad_citas_facturadas: citasSemana.length,
  ingreso_total: ingresoTotal,
  costo_operativo: costoOperativoSemanal,
  roi_porcentaje: roi,
  detalle_citas: citasSemana
};

